import csv
targets={
 "Zone_F1_Z01.Zone_Air_Temperature_Sensor":"Core_bottom",
 "Zone_F3_Z03.Zone_Air_Temperature_Sensor":"Perimeter_top_ZN_2",
}
with open(CATALOG_CSV) as f:
    r=list(csv.DictReader(f))
found={}
for row in r:
    uri=row["point_uri"]
    for k in targets:
        if uri.endswith("#"+k):
            found[k]=row
for k,row in found.items():
    print(targets[k], row["timeseries_id"], row["point_class"], row["unit"])
print("found keys", list(found))
